function out = COMSOL_builder(outputFile, initialSolnum)
%% MY THERMOFLASK MODEL - FRESH BUILDER (Reviews)
% I updated this builder from Reviews.m (COMSOL 6.3, 12 Nov 2026).
%
% PURPOSE:
%   I rebuild the model from a clean COMSOL session before solving anything.
%   I keep the original geometry, physics, meshes and custom solvers.
%   I also keep the Results structure so I can check the thermal mapping later.
%   A timestamped log records where the reconstruction is and how long it takes.
%
% EXAMPLES - from COMSOL with MATLAB R2022b:
%   COMSOL_builder();
%   COMSOL_builder('D:\Elena\COMSOL_Reference.mph');
%   COMSOL_builder('D:\Elena\COMSOL_Reference_FirstInit.mph','first');
%
% INPUT:
%   outputFile      - destination .mph file (new, does not overwrite source).
%   initialSolnum   - 'last' (default/correct transfer) or 'first' (export).
%
% IMPORTANT DIAGNOSTIC:
%   I keep the Post Cooling initial state linked to the last Downhole solution.
%   By default, Post Cooling starts from the END of sol2.
%   The 'first' option is for diagnostics only.
%   Both transient solvers (sol2 and sol5) enforce max BDF step = 1 min.
%   Output storage stays at 0,5,10,...,1200 min (or earlier stop).
%
% BUILD ONLY: no std1..std5 runNoGen, no Derived Value evaluation.
%   To solve sequentially after build, use COMSOL_ReferenceRun.m.
%
% UNCHANGED MODEL ASSUMPTIONS:
%   SK_length=150 mm fixed; INS1_l, INS2_l, PCM_SH_l independent;
%   TF_L derives from their sum plus the three other segment lengths.
%   Study std6 (Morris UQ) is retained AS EXPORTED, with old 10-parameter
%   bounds. DO NOT compute std6 until the updated Morris design is specified.
%
% I will validate this revised geometry and solver in COMSOL LiveLink.
% I do not compute std6 because the Morris variable ranges are being updated.

if nargin < 1 || isempty(outputFile)
    outputFile = fullfile('D:\Elena', 'COMSOL_Reference.mph');
end
if nargin < 2 || isempty(initialSolnum)
    initialSolnum = 'last';
end
outputFile = char(outputFile);
initialSolnum = lower(char(initialSolnum));
assert(ismember(initialSolnum, {'last','first'}), ...
    'initialSolnum must be ''last'' or ''first''.');
folder = fileparts(outputFile);
if ~isempty(folder) && ~isfolder(folder)
    mkdir(folder);
end

%% 1. START THE BUILD LOG
% I keep a separate log for each output model. Re-running the builder starts
% a new log, so I do not confuse messages from two different builds.
[~,outputBase] = fileparts(outputFile);
logFile = fullfile(folder, [outputBase '_Builder_Log.txt']);
errorFile = fullfile(folder, [outputBase '_Builder_Error.txt']);
if isempty(folder)
    logFile = fullfile(pwd, [outputBase '_Builder_Log.txt']);
    errorFile = fullfile(pwd, [outputBase '_Builder_Error.txt']);
end
fid = fopen(logFile,'w');
assert(fid >= 0, 'Cannot create builder log: %s', logFile);
fclose(fid);

import com.comsol.model.*
import com.comsol.model.util.*

totalTimer = tic;
tfOpen5Log(logFile,'==============================================================');
tfOpen5Log(logFile,'COMSOL REFERENCE - FRESH MODEL BUILDER');
tfOpen5Log(logFile,'Output MPH: %s', outputFile);
tfOpen5Log(logFile,'Post Cooling initial solution: sol2 / %s', initialSolnum);
tfOpen5Log(logFile,'Model is built only; no physics studies are solved here.');

% I use a dedicated COMSOL tag to avoid removing any other open model.
try
    ModelUtil.remove('COMSOLReferenceBuild');
catch
    % Nothing to remove if this is the first build in this MATLAB session.
end

% I request COMSOL's native progress messages where LiveLink supports them.
% The builder log remains available even when that output is unavailable.
try
    ModelUtil.showProgress(true);
    tfOpen5Log(logFile,'COMSOL native progress display requested.');
catch progressME
    tfOpen5Log(logFile,'COMSOL native progress display unavailable: %s',progressME.message);
end

% The outer try/catch helps me identify the last completed construction step.
try

%% 2. REBUILD THE MODEL FROM THE EXPORTED COMSOL COMMANDS
% I preserve the original order of the COMSOL API calls. Some selections
% depend on that order, so I only add diagnostic messages and comments.

%% 1. PARAMETERS, FUNCTIONS AND COMPONENT
% I keep the settings exported from the updated COMSOL reference.
currentStage = '01/22 | Parameters, functions and component';
stageTimer = tic;
tfOpen5Log(logFile,'START %s',currentStage);

model = ModelUtil.create('COMSOLReferenceBuild');

model.modelPath('D:\Elena');

model.label('COMSOL_Reference.mph');

model.param.set('TO_N_ref', '200 [1/m]', 'Thermal Oil Swept element density');
model.param.set('TO_h_ref', '2[mm]', 'Thermal Oil tetrahedral maximum size');
model.param.set('PCM_h_ref', '2.5[mm]', 'PCM Free Quadrilateral');
model.param.set('PCM_h_z', '5[mm]', 'PCM Layers of Swept mesh');
model.param.set('currentiter', '0');
model.param.group.create('par3');
model.param('par3').set('T_initial', '273.15+25[K]', 'Initial ambient temperature');
model.param('par3').set('T_ambient', '273.15 + 25[K]', 'Ambient temperature in post cooling');
model.param('par3').set('h_air', '5.5[W/(m^2*K)]', 'Free Air HTC');
model.param('par3').set('T_air', '273.15 + 25 [K]', 'Inlet cooling air temeprature');
model.param('par3').set('SwitchTime', '360', 'Switch between downhole e post operation');
model.param('par3').set('T0', 'T_initial', 'Volume reference temperature');
model.param.group.create('par5');
model.param('par5').set('SK_length', '150[mm]', 'Skeleton total length');
model.param('par5').set('SK_height', '15[mm]', 'Thickness of the skeleton');
model.param('par5').set('d_int', '4[mm]', 'Internal Diameter pipes');
model.param('par5').set('PCM_SH_l', '450[mm]', 'PCM Shell total length');
model.param('par5').set('INS1_l', '150[mm]', 'Insulator 1 Length');
model.param('par5').set('AirHE_l', '150[mm]', 'Additional length of the pipe in the air HE');
model.param('par5').set('fin_pitch', '2[mm]', 'Distance between fins');
model.param('par5').set('fin_thick', '0.5[mm]', 'Fin thickness');
model.param('par5').set('INS2_l', '150[mm]', 'Insulator 2 length');
model.param('par5').set('tube_s', '2[mm]', 'pipe thickness');
model.param('par5').set('pipe_gap', '10[mm]', 'distance between center of two pipes');
model.param('par5').set('v_air', '10[m/s]', 'Velocity of the inlet air');
model.param('par5').set('v_oil_down', '0.1[m/s]', 'Velocity of oil after the pump');
model.param('par5').set('fin_extension', '2[mm]', 'Fine extension over the external radius of the pipe');
model.param('par5').set('v_oil_up', '0.1[m/s]', 'Velocity of oil after the pump');
model.param.group.create('par6');
model.param('par6').set('R_ext', '36[mm]', 'Reference outer radius');
model.param('par6').set('R_int', '30[mm]', 'Reference inner radius');
model.param('par6').set('cut_length', '10[mm]', 'Top and bottom but length');
model.param('par6').set('cut_height', '3[mm]', 'Top and bottom cut height');
model.param('par6').set('gap', '13[mm]', 'Contact o ring between elements');
model.param('par6').set('TF_R', '45[mm]', 'Thermoflask external radius of the thermoflask');
model.param('par6').set('h_pad', '1[mm]', 'thickness of thermal pad');
model.param('par6').set('Blanket_t', '5[mm]', 'Blanket Areogel thickness');
model.param('par6').set('PCM_gap1', '(21-13)[mm]', 'Gap between shell and PCM skeleton side');
model.param('par6').set('PCM_gap2', '(19-13)[mm]', 'Gap between shell and PCM insulator side');
model.param('par6').set('AD_l', '150[mm]', 'Adapter length');
model.param('par6').set('TWV_l', '50[mm]', 'Three way valve space');
model.param.group.create('par7');
model.param('par7').set('TF_L', 'INS1_l+AD_l+SK_length+PCM_SH_l+TWV_l+INS2_l', 'Thermoflask total length');
model.param('par7').set('AirHE_Shell_l', 'AirHE_l+R_int-pipe_gap+3*gap', 'Length of the Air He Shell');
model.param('par7').set('n', 'floor((AirHE_l-fin_pitch)/fin_pitch)', 'Number of fins');
model.param('par7').set('fin_R', '(d_int/2+tube_s)+fin_extension', 'Esternal radius of fins');
model.param('par7').set('Q_down', 'pi*d_int*d_int/4*(v_oil_down)', 'Flow rate of the pump in downhole heating');
model.param('par7').set('Q_up', 'pi*d_int*d_int/4*(v_oil_up)', 'Flow rate of the pump in cooling');
model.param.label('Mesh Parameters');
model.param('par3').label('Temperatures');
model.param('par5').label('Geometry parameters to be optimized');
model.param('par6').label('Geometry parameters fixed');
model.param('par7').label('Geometry parameters calculated');

model.component.create('comp1', true);

model.component('comp1').geom.create('geom1', 3);

model.component('comp1').label('Geometry without fins');

model.result.table.create('tbl1', 'Table');
model.result.table.create('tbl2', 'Table');
model.result.table.create('tbl3', 'Table');
model.result.table.create('tbl4', 'Table');
model.result.table.create('tbl5', 'Table');
model.result.table.create('tbl6', 'Table');
model.result.table.create('tbl7', 'Table');
model.result.table.create('tbl8', 'Table');
model.result.table.create('tbl9', 'Table');

model.func.create('step1', 'Step');
model.func.create('step2', 'Step');
model.func.create('int5', 'Interpolation');
model.func.create('int6', 'Interpolation');
model.func('step1').label('Temperature smoothing');
model.func('step1').set('location', 30);
model.func('step1').set('smooth', 30);
model.func('step1').set('locationdef', 'end');
model.func('step2').label('Flow rate smoothing');
model.func('step2').set('location', 1);
model.func('step2').set('smooth', 2);
model.func('int5').label('Dynamic viscosity of thermal oil');
model.func('int5').set('funcnametable', {'int1' '1'});
model.func('int5').set('funcname', 'MuOil');
model.func('int5').set('table', {'-25' '0.326';  ...
'0' '0.169';  ...
'25' '0.0965';  ...
'50' '0.0608';  ...
'100' '0.0282';  ...
'150' '0.0154';  ...
'200' '0.00938'});
model.func('int5').set('interp', 'cubicspline');
model.func('int5').set('extrap', 'interior');
model.func('int5').set('fununit', {'Pa*s'});
model.func('int5').set('argunit', {'degC'});
model.func('int6').label('Density of thermal oil');
model.func('int6').set('funcnametable', {'int2' '1'});
model.func('int6').set('funcname', 'RhoOil');
model.func('int6').set('table', {'-25' '1006';  ...
'0' '987';  ...
'25' '965';  ...
'50' '944';  ...
'100' '902';  ...
'150' '862';  ...
'200' '823'});
model.func('int6').set('interp', 'cubicspline');
model.func('int6').set('extrap', 'interior');
model.func('int6').set('fununit', {'kg/(m^3)'});
model.func('int6').set('argunit', {'degC'});

model.component('comp1').mesh.create('mesh1');
model.component('comp1').mesh.create('mesh2');
model.component('comp1').mesh.create('mesh6');
model.component('comp1').mesh.create('mesh5');

model.geom.create('part1', 'Part', 3);
model.geom.create('part2', 'Part', 3);
model.geom.create('part3', 'Part', 3);
model.geom.create('part10', 'Part', 3);
model.geom.create('part11', 'Part', 3);
model.geom.create('part4', 'Part', 3);
model.geom.create('part14', 'Part', 3);
model.geom.create('part15', 'Part', 3);
model.geom.create('part13', 'Part', 3);
model.geom.create('part7', 'Part', 3);
tfOpen5Log(logFile,'DONE  %s (%.1f s)',currentStage,toc(stageTimer));

%% 2. CAD PART: SKELETON
% I keep the settings exported from the updated COMSOL reference.
currentStage = '02/22 | CAD part: Skeleton';
stageTimer = tic;
tfOpen5Log(logFile,'START %s',currentStage);

model.geom('part1').label('Skeleton');
model.geom('part1').lengthUnit('mm');
model.geom('part1').geomRep('cadps');
model.geom('part1').designBooleans(true);
model.geom('part1').localParam.set('SK_ext_length', '21[mm]', 'Skeleton distance between end and air');
model.geom('part1').localParam.set('SK_Air_l', '64.5*2[mm]', 'Length of the central cut');
model.geom('part1').create('wp6', 'WorkPlane');
model.geom('part1').feature('wp6').label('Work Plane 1');
model.geom('part1').feature('wp6').set('quickz', '-SK_length/2');
model.geom('part1').feature('wp6').set('unite', true);
model.geom('part1').feature('wp6').geom.create('c1', 'Circle');
model.geom('part1').feature('wp6').geom.feature('c1').set('r', 'R_ext');
model.geom('part1').feature('wp6').geom.create('r1', 'Rectangle');
model.geom('part1').feature('wp6').geom.feature('r1').set('size', {'cut_length' 'cut_height'});
model.geom('part1').feature('wp6').geom.feature('r1').set('pos', {'-cut_length/2' 'R_ext-cut_height'});
model.geom('part1').feature('wp6').geom.create('mir1', 'Mirror');
model.geom('part1').feature('wp6').geom.feature('mir1').set('keep', true);
model.geom('part1').feature('wp6').geom.feature('mir1').set('axis', [0 1]);
model.geom('part1').feature('wp6').geom.feature('mir1').selection('input').set({'r1'});
model.geom('part1').feature('wp6').geom.create('c2', 'Circle');
model.geom('part1').feature('wp6').geom.feature('c2').set('r', 'R_int');
model.geom('part1').feature('wp6').geom.create('dif1', 'Difference');
model.geom('part1').feature('wp6').geom.feature('dif1').selection('input').set({'c1'});
model.geom('part1').feature('wp6').geom.feature('dif1').selection('input2').set({'c2' 'mir1' 'r1'});
model.geom('part1').create('ext7', 'Extrude');
model.geom('part1').feature('ext7').setIndex('distance', 'SK_length', 0);
model.geom('part1').feature('ext7').selection('input').set({'wp6'});
model.geom('part1').create('wp2', 'WorkPlane');
model.geom('part1').feature('wp2').active(false);
model.geom('part1').feature('wp2').label('Gap1');
model.geom('part1').feature('wp2').set('quickz', '-SK_length/2+2');
model.geom('part1').feature('wp2').set('unite', true);
model.geom('part1').feature('wp2').geom.create('c1', 'Circle');
model.geom('part1').feature('wp2').geom.feature('c1').set('r', 'R_int');
model.geom('part1').create('ext2', 'Extrude');
model.geom('part1').feature('ext2').active(false);
model.geom('part1').feature('ext2').set('inputhandling', 'remove');
model.geom('part1').feature('ext2').setIndex('distance', 'gap+2', 0);
model.geom('part1').feature('ext2').set('reverse', true);
model.geom('part1').feature('ext2').selection('input').set({'wp2'});
model.geom('part1').create('wp3', 'WorkPlane');
model.geom('part1').feature('wp3').active(false);
model.geom('part1').feature('wp3').label('Gap2');
model.geom('part1').feature('wp3').set('quickz', 'SK_length/2-2');
model.geom('part1').feature('wp3').set('unite', true);
model.geom('part1').feature('wp3').geom.create('c1', 'Circle');
model.geom('part1').feature('wp3').geom.feature('c1').set('r', 'R_int');
model.geom('part1').create('ext3', 'Extrude');
model.geom('part1').feature('ext3').active(false);
model.geom('part1').feature('ext3').set('inputhandling', 'remove');
model.geom('part1').feature('ext3').setIndex('distance', 'gap+2', 0);
model.geom('part1').feature('ext3').selection('input').set({'wp3'});
model.geom('part1').create('uni1', 'Union');
model.geom('part1').feature('uni1').active(false);
model.geom('part1').feature('uni1').set('intbnd', false);
model.geom('part1').feature('uni1').selection('input').set({'ext2' 'ext3' 'ext7'});
model.geom('part1').create('wp7', 'WorkPlane');
model.geom('part1').feature('wp7').set('quickz', '-SK_length/2+gap');
model.geom('part1').feature('wp7').set('unite', true);
model.geom('part1').feature('wp7').geom.create('r1', 'Rectangle');
model.geom('part1').feature('wp7').geom.feature('r1').set('size', {'sqrt(R_int*R_int-0.5*SK_height*0.5*SK_height)*2' 'SK_height'});
model.geom('part1').feature('wp7').geom.feature('r1').set('base', 'center');
model.geom('part1').create('ext8', 'Extrude');
model.geom('part1').feature('ext8').setIndex('distance', 'SK_length-2*gap', 0);
model.geom('part1').feature('ext8').selection('input').set({'wp7'});
model.geom('part1').create('wp5', 'WorkPlane');
model.geom('part1').feature('wp5').label('Skeleton end');
model.geom('part1').feature('wp5').set('quickz', '-SK_length/2+gap');
model.geom('part1').feature('wp5').set('unite', true);
model.geom('part1').feature('wp5').geom.create('c3', 'Circle');
model.geom('part1').feature('wp5').geom.feature('c3').label('External tube diameter in');
model.geom('part1').feature('wp5').geom.feature('c3').set('r', 'd_int/2+tube_s');
model.geom('part1').feature('wp5').geom.feature('c3').set('pos', {'-pipe_gap' '0'});
model.geom('part1').feature('wp5').geom.create('c4', 'Circle');
model.geom('part1').feature('wp5').geom.feature('c4').label('Internal tube diameter in ');
model.geom('part1').feature('wp5').geom.feature('c4').set('r', 'd_int/2');
model.geom('part1').feature('wp5').geom.feature('c4').set('pos', {'-pipe_gap' '0'});
model.geom('part1').feature('wp5').geom.create('c5', 'Circle');
model.geom('part1').feature('wp5').geom.feature('c5').label('External small diameter out');
model.geom('part1').feature('wp5').geom.feature('c5').set('r', 'd_int/2+tube_s');
model.geom('part1').feature('wp5').geom.feature('c5').set('pos', {'pipe_gap' '0'});
model.geom('part1').feature('wp5').geom.create('c6', 'Circle');
model.geom('part1').feature('wp5').geom.feature('c6').label('Internal diameter out');
model.geom('part1').feature('wp5').geom.feature('c6').set('r', 'd_int/2');
model.geom('part1').feature('wp5').geom.feature('c6').set('pos', {'pipe_gap' '0'});
model.geom('part1').create('ext6', 'Extrude');
model.geom('part1').feature('ext6').setIndex('distance', 'SK_length-2*gap', 0);
model.geom('part1').feature('ext6').selection('input').set({'wp5'});
model.geom('part1').create('dif4', 'Difference');
model.geom('part1').feature('dif4').selection('input').set({'ext8' 'ext7'});
model.geom('part1').feature('dif4').selection('input2').set({'ext6'});
model.geom('part1').nodeGroup.create('grp6');
model.geom('part1').nodeGroup('grp6').label('Shell');
model.geom('part1').nodeGroup('grp6').placeAfter([]);
model.geom('part1').nodeGroup('grp6').add('wp6');
model.geom('part1').nodeGroup('grp6').add('ext7');
model.geom('part1').nodeGroup.create('grp2');
model.geom('part1').nodeGroup('grp2').label('O-ring 1');
model.geom('part1').nodeGroup('grp2').placeAfter([]);
model.geom('part1').nodeGroup('grp2').add('wp2');
model.geom('part1').nodeGroup('grp2').add('ext2');
model.geom('part1').nodeGroup.create('grp1');
model.geom('part1').nodeGroup('grp1').label('O-ring 2');
model.geom('part1').nodeGroup('grp1').placeAfter([]);
model.geom('part1').nodeGroup('grp1').add('wp3');
model.geom('part1').nodeGroup('grp1').add('ext3');
model.geom('part1').nodeGroup('grp1').add('uni1');
model.geom('part1').nodeGroup.create('grp3');
model.geom('part1').nodeGroup('grp3').label('Cold Plate');
model.geom('part1').nodeGroup('grp3').placeAfter([]);
model.geom('part1').nodeGroup('grp3').add('wp7');
model.geom('part1').nodeGroup('grp3').add('ext8');
model.geom('part1').nodeGroup.create('grp4');
model.geom('part1').nodeGroup('grp4').label('Pipes holes');
model.geom('part1').nodeGroup('grp4').placeAfter([]);
model.geom('part1').nodeGroup('grp4').add('wp5');
model.geom('part1').nodeGroup('grp4').add('ext6');
model.geom('part1').nodeGroup('grp4').add('dif4');
tfOpen5Log(logFile,'Building geometry: part1');
model.geom('part1').run;
tfOpen5Log(logFile,'DONE  %s (%.1f s)',currentStage,toc(stageTimer));

%% 3. CAD PART: THERMAL PADS
% I keep the settings exported from the updated COMSOL reference.
currentStage = '03/22 | CAD part: Thermal pads';
stageTimer = tic;
tfOpen5Log(logFile,'START %s',currentStage);

model.geom('part2').label('Thermal Pads');
model.geom('part2').lengthUnit('mm');
model.geom('part2').geomRep('cadps');
model.geom('part2').designBooleans(true);
model.geom('part2').localParam.set('l', '50[mm]', 'length of thermal pad');
model.geom('part2').create('wp1', 'WorkPlane');
model.geom('part2').feature('wp1').label('THP Base 1');
model.geom('part2').feature('wp1').set('quickplane', 'zx');
model.geom('part2').feature('wp1').set('quicky', 'SK_height/2');
model.geom('part2').feature('wp1').set('unite', true);
model.geom('part2').feature('wp1').geom.create('r1', 'Rectangle');
model.geom('part2').feature('wp1').geom.feature('r1').set('size', {'l' 'l'});
model.geom('part2').feature('wp1').geom.feature('r1').set('base', 'center');
model.geom('part2').create('ext1', 'Extrude');
model.geom('part2').feature('ext1').setIndex('distance', 'h_pad', 0);
model.geom('part2').feature('ext1').selection('input').set({'wp1'});
model.geom('part2').create('wp2', 'WorkPlane');
model.geom('part2').feature('wp2').label('THP Base 2');
model.geom('part2').feature('wp2').set('quickplane', 'zx');
model.geom('part2').feature('wp2').set('quicky', '-SK_height/2');
model.geom('part2').feature('wp2').set('unite', true);
model.geom('part2').feature('wp2').geom.create('r1', 'Rectangle');
model.geom('part2').feature('wp2').geom.feature('r1').set('size', {'l' 'l'});
model.geom('part2').feature('wp2').geom.feature('r1').set('base', 'center');
model.geom('part2').create('ext2', 'Extrude');
model.geom('part2').feature('ext2').setIndex('distance', 'h_pad', 0);
model.geom('part2').feature('ext2').set('reverse', true);
model.geom('part2').feature('ext2').selection('input').set({'wp2'});
tfOpen5Log(logFile,'Building geometry: part2');
model.geom('part2').run;
tfOpen5Log(logFile,'DONE  %s (%.1f s)',currentStage,toc(stageTimer));

%% 4. CAD PART: HEAT SOURCES
% I keep the settings exported from the updated COMSOL reference.
currentStage = '04/22 | CAD part: Heat sources';
stageTimer = tic;
tfOpen5Log(logFile,'START %s',currentStage);

model.geom('part3').label('Heat Sources');
model.geom('part3').lengthUnit('mm');
model.geom('part3').geomRep('cadps');
model.geom('part3').designBooleans(true);
