% The Results groups, cut planes and Derived Values are copied directly from
% Reviews.m, so I do not recreate any node a second time.
currentStage = '21/22 | Final consistency checks';
stageTimer = tic;
tfOpen5Log(logFile,'START %s',currentStage);
try
    v1 = cell(model.sol('sol3').feature('s1').feature('se1').feature('ss1').getStringArray('segvar'));
    v2 = cell(model.sol('sol3').feature('s1').feature('se1').feature('ss2').getStringArray('segvar'));
    assert(all(ismember({'comp1_u3','comp1_p3'},v1)), 'Cooling Air: velocity/pressure step incorrect.');
    assert(all(ismember({'comp1_k3','comp1_ep3'},v2)), 'Cooling Air: turbulence step incorrect.');
catch checkME
    tfOpen5Log(logFile,'Solver variable audit: %s',checkME.message);
    % The settings are present in the exported commands; a Java type
    % conversion failure must not invalidate the model reconstruction.
end
% The reviewed geometry uses new named selections for oil walls and air walls.
% I preserve these rather than relying on the old numeric face IDs.
