tfOpen5Log(logFile,'DONE  %s (%.1f s)',currentStage,toc(stageTimer));

%% 22. SAVE THE FRESH MODEL
% The five physical studies are NOT computed by this builder.
% My ReferenceRun script will save the completed solution separately.
currentStage = '22/22 | Save fresh model';
stageTimer = tic;
tfOpen5Log(logFile,'START %s',currentStage);
[~,saveName,saveExt] = fileparts(outputFile);
model.label([saveName saveExt]);
tfOpen5Log(logFile,'Saving fresh MPH: %s',outputFile);
mphsave(model,outputFile);
tfOpen5Log(logFile,'DONE  %s (%.1f s)',currentStage,toc(stageTimer));
tfOpen5Log(logFile,'BUILD COMPLETE: %.2f min',toc(totalTimer)/60);
tfOpen5Log(logFile,'Next: COMSOL_ReferenceRun()');
tfOpen5Log(logFile,'Builder log: %s',logFile);
out = model;

catch ME
    % I save the complete error message and the current phase separately.
    tfOpen5Log(logFile,'FAILED in %s after %.1f s',currentStage,toc(totalTimer));
    tfOpen5Log(logFile,'ERROR: %s',ME.message);
    fid = fopen(errorFile,'w');
    if fid >= 0
        fprintf(fid,'TF_OPEN5 Builder - error report\n');
        fprintf(fid,'Stage: %s\n',currentStage);
        fprintf(fid,'Elapsed time: %.1f s\n\n',toc(totalTimer));
        fprintf(fid,'%s\n',getReport(ME,'extended','hyperlinks','off'));
        fclose(fid);
        tfOpen5Log(logFile,'Full error report: %s',errorFile);
    end
    rethrow(ME);
end
end

function tfOpen5Log(logFile,formatText,varargin)
%% LOG TO THE COMMAND WINDOW AND TO MY BUILD FILE
% I keep logging independent from the COMSOL model, so a failed solver or
% geometry operation does not prevent the messages from being recorded.
message = sprintf(formatText,varargin{:});
line = sprintf('[%s] [TF_OPEN5 BUILDER] %s', ...
    datestr(now,'yyyy-mm-dd HH:MM:SS'),message);
fprintf('%s\n',line);
fid = fopen(logFile,'a');
if fid >= 0
    fprintf(fid,'%s\n',line);
    fclose(fid);
else
    warning('Elena:BuilderLog','Cannot append to log: %s',logFile);
end
end
